import React, { useState, useEffect } from 'react';
import { LayoutGrid, ShoppingBasket, DollarSign, PlusCircle, AlertTriangle, ArrowUp, CheckCircle, ChevronRight } from 'lucide-react';

// --- MOCK DATA ---
const initialInventory = [
  { id: 1, name: 'Heirloom Tomatoes', stock: 3, unit: 'lbs', price: 4.50, category: 'Vegetables', weeklySales: 45 },
  { id: 2, name: 'Organic Kale', stock: 15, unit: 'bunches', price: 3.00, category: 'Greens', weeklySales: 25 },
  { id: 3, name: 'Sweet Corn', stock: 48, unit: 'ears', price: 0.75, category: 'Vegetables', weeklySales: 112 },
  { id: 4, name: 'Artisanal Honey', stock: 8, unit: 'jars', price: 12.00, category: 'Pantry', weeklySales: 10 },
  { id: 5, name: 'Rainbow Chard', stock: 11, unit: 'bunches', price: 3.25, category: 'Greens', weeklySales: 18 },
  { id: 6, name: 'Zucchini', stock: 25, unit: 'lbs', price: 2.00, category: 'Vegetables', weeklySales: 30 },
];

const salesData = {
  today: 285.50,
  weekly: 1142.00,
  trend: 15,
};

// --- SUB-COMPONENTS FOR SCREENS ---
const DashboardScreen = ({ setCurrentScreen, inventory }) => {
  const lowStockItem = inventory.find(item => item.stock < 5);
  const topSeller = [...inventory].sort((a, b) => b.weeklySales - a.weeklySales)[0];

  return (
    <div className="p-4 space-y-6 animate-fade-in">
      <div>
        <p className="text-sm text-gray-500">Welcome back,</p>
        <h1 className="text-2xl font-bold text-gray-800">Maria's Farm Fresh</h1>
      </div>

      {lowStockItem && (
        <div onClick={() => setCurrentScreen('inventory')} className="cursor-pointer bg-amber-50 border-l-4 border-amber-400 p-4 flex items-center space-x-3 rounded-r-lg shadow-sm hover:bg-amber-100 transition-colors duration-200">
          <AlertTriangle className="h-6 w-6 text-amber-500" />
          <div>
            <p className="font-semibold text-amber-800">Low Stock Alert</p>
            <p className="text-sm text-amber-700">{lowStockItem.name}: only {lowStockItem.stock} {lowStockItem.unit} left.</p>
          </div>
        </div>
      )}

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-200">
          <p className="text-sm text-gray-500">Sales Today</p>
          <p className="text-2xl font-semibold text-gray-800">${salesData.today.toFixed(2)}</p>
        </div>
        <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-200">
          <p className="text-sm text-gray-500">Weekly Trend</p>
          <div className="flex items-center">
            <p className="text-2xl font-semibold text-green-700">+{salesData.trend}%</p>
            <ArrowUp className="h-5 w-5 text-green-600 ml-1" />
          </div>
        </div>
      </div>

      <div>
        <h2 className="text-lg font-semibold text-gray-800 mb-2">Top Sellers This Week</h2>
        <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-200 space-y-3">
          <div className="flex justify-between items-center">
            <p className="font-medium text-gray-700">1. {topSeller.name}</p>
            <p className="text-sm text-gray-500">{topSeller.weeklySales} {topSeller.unit} sold</p>
          </div>
          <div className="w-full bg-gray-200 rounded-full h-2.5">
            <div className="bg-green-600 h-2.5 rounded-full" style={{ width: '95%' }}></div>
          </div>
        </div>
      </div>
    </div>
  );
};

const InventoryScreen = ({ inventory, setInventory, newProductAdded, setNewProductAdded }) => {
  useEffect(() => {
    if (newProductAdded) {
      const timer = setTimeout(() => setNewProductAdded(false), 3000);
      return () => clearTimeout(timer);
    }
  }, [newProductAdded, setNewProductAdded]);

  return (
    <div className="p-4 space-y-4 animate-fade-in">
      <h1 className="text-2xl font-bold text-gray-800">Inventory</h1>
      {newProductAdded && (
        <div className="bg-green-50 text-green-800 p-3 rounded-lg flex items-center space-x-2 shadow-sm transition-opacity duration-300">
          <CheckCircle className="h-5 w-5" />
          <p className="text-sm font-medium">'Sun Gold Cherry Tomatoes' added successfully!</p>
        </div>
      )}
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 divide-y divide-gray-200">
        {inventory.map(item => (
          <div key={item.id} className="p-3 flex justify-between items-center">
            <div>
              <p className="font-semibold text-gray-800">{item.name}</p>
              <p className="text-sm text-gray-500">{item.stock} {item.unit} in stock</p>
            </div>
            <div className="text-right">
              <p className="font-medium text-gray-700">${item.price.toFixed(2)}</p>
              <p className={`text-sm ${item.stock < 10 ? 'text-amber-600' : 'text-green-600'}`}>
                {item.stock < 10 ? 'Low Stock' : 'In Stock'}
              </p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

const AddProductScreen = ({ setCurrentScreen, setInventory, setNewProductAdded }) => {
  const handleSubmit = (e) => {
    e.preventDefault();
    const newProduct = {
      id: Date.now(),
      name: 'Sun Gold Cherry Tomatoes',
      stock: 20,
      unit: 'pints',
      price: 5.50,
      category: 'Vegetables',
      weeklySales: 0
    };
    setInventory(prev => [newProduct, ...prev]);
    setNewProductAdded(true);
    setCurrentScreen('inventory');
  };

  return (
    <div className="p-4 space-y-6 animate-fade-in">
      <h1 className="text-2xl font-bold text-gray-800">Add New Product</h1>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="text-sm font-medium text-gray-700">Product Name</label>
          <input type="text" defaultValue="Sun Gold Cherry Tomatoes" className="mt-1 block w-full px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-green-500 focus:border-green-500" />
        </div>
        <div>
          <label className="text-sm font-medium text-gray-700">Category</label>
          <select defaultValue="Vegetables" className="mt-1 block w-full px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-green-500 focus:border-green-500">
            <option>Vegetables</option>
            <option>Greens</option>
            <option>Pantry</option>
            <option>Fruits</option>
          </select>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="text-sm font-medium text-gray-700">Price (per unit)</label>
            <input type="text" defaultValue="$5.50" className="mt-1 block w-full px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-green-500 focus:border-green-500" />
          </div>
          <div>
            <label className="text-sm font-medium text-gray-700">In Stock</label>
            <input type="text" defaultValue="20 pints" className="mt-1 block w-full px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-green-500 focus:border-green-500" />
          </div>
        </div>
        <button type="submit" className="w-full bg-green-700 text-white font-semibold py-3 px-4 rounded-lg shadow-md hover:bg-green-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500 transition-all duration-200">
          Add Product to Inventory
        </button>
      </form>
    </div>
  );
};

const PlaceholderScreen = ({ screenName }) => (
    <div className="p-4 animate-fade-in flex items-center justify-center h-full">
        <h1 className="text-2xl font-bold text-gray-400">{screenName} Screen</h1>
    </div>
);

// --- NAVIGATION ---
const BottomNavBar = ({ currentScreen, setCurrentScreen }) => {
  const navItems = [
    { id: 'dashboard', label: 'Home', icon: LayoutGrid },
    { id: 'inventory', label: 'Inventory', icon: ShoppingBasket },
    { id: 'add_product', label: 'Add', icon: PlusCircle },
    { id: 'sales', label: 'Sales', icon: DollarSign },
  ];

  return (
    <div className="fixed inset-x-0 bottom-0 bg-white border-t border-gray-200 shadow-lg">
      <div className="flex justify-around max-w-md mx-auto">
        {navItems.map(item => {
          const isActive = currentScreen === item.id;
          return (
            <button
              key={item.id}
              onClick={() => setCurrentScreen(item.id)}
              className={`flex flex-col items-center justify-center w-full pt-3 pb-2 text-sm transition-colors duration-200 ${isActive ? 'text-green-700' : 'text-gray-500 hover:text-green-600'}`}>
              <item.icon className="h-6 w-6 mb-1" />
              <span>{item.label}</span>
              {isActive && <div className="w-8 h-1 bg-green-700 rounded-full mt-1"></div>}
            </button>
          );
        })}
      </div>
    </div>
  );
};

// --- MAIN APP COMPONENT ---
export default function FarmstandProPrototype() {
  const [currentScreen, setCurrentScreen] = useState('dashboard');
  const [inventory, setInventory] = useState(initialInventory);
  const [newProductAdded, setNewProductAdded] = useState(false);

  const renderScreen = () => {
    switch (currentScreen) {
      case 'dashboard':
        return <DashboardScreen setCurrentScreen={setCurrentScreen} inventory={inventory} />;
      case 'inventory':
        return <InventoryScreen inventory={inventory} setInventory={setInventory} newProductAdded={newProductAdded} setNewProductAdded={setNewProductAdded} />;
      case 'add_product':
        return <AddProductScreen setCurrentScreen={setCurrentScreen} setInventory={setInventory} setNewProductAdded={setNewProductAdded} />;
      case 'sales':
        return <PlaceholderScreen screenName="Sales & Reports" />;
      default:
        return <DashboardScreen setCurrentScreen={setCurrentScreen} inventory={inventory} />;
    }
  };

  return (
    <div className="w-full max-w-md mx-auto bg-gray-50 font-sans rounded-2xl shadow-2xl overflow-hidden ring-1 ring-gray-900/5" style={{ fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif", height: '812px' }}>
      <div className="flex flex-col h-full">
        <main className="flex-grow overflow-y-auto pb-24">
          {renderScreen()}
        </main>
        <BottomNavBar currentScreen={currentScreen} setCurrentScreen={setCurrentScreen} />
      </div>
      <style>{`.animate-fade-in { animation: fadeIn 0.3s ease-in-out; } @keyframes fadeIn { 0% { opacity: 0; transform: translateY(10px); } 100% { opacity: 1; transform: translateY(0); } }`}</style>
    </div>
  );
}
